// One probe per intent, not one per letter of the alphabet.
//
// Asking for the brand alone returns whatever is most common, which is usually
// "login" and "pricing" and never changes. The seeds are the phrasings a buyer
// with a problem actually types, and they surface a different set.
const cfg = $('Settings').first().json;
const brand = String(cfg.brand || '').trim();

if (!brand) {
  throw new Error('Put your brand name in Settings before running this.');
}

const seeds = String(cfg.seeds || '')
  .split('|')
  .map(function (s) { return s.trim(); })
  .filter(Boolean);

const probes = [brand].concat(seeds.map(function (s) {
  // A seed either follows the brand ("brand cancel") or wraps it ("is brand"),
  // which is what the placeholder marks.
  return s.indexOf('*') >= 0 ? s.replace('*', brand) : brand + ' ' + s;
}));

return probes.slice(0, 12).map(function (p, i) {
  return { json: { probe: p, index: i } };
});

// Both branches land here through the Merge, which is what guarantees the
// search has finished before anything is counted.
//
// Two different shapes arrive. The autocomplete endpoint answers with a bare
// JSON array - ["semrush",[["semrush",0,[512]],["semrush<b> pricing</b>",...]]] -
// where the completion is wrapped in <b> tags marking the part Google added.
// The SERP answers with the usual envelope. Both are read here rather than in
// two nodes, because what comes out is one list either way.
const cfg = $('Settings').first().json;
const brand = String(cfg.brand || '').trim();
const brandKey = brand.toLowerCase();

function unwrap(x) {
  let p = x;
  if (p && p.body != null) { p = p.body; }
  if (typeof p === 'string') {
    const t = p.trim();
    if (t.charAt(0) === '{' || t.charAt(0) === '[') {
      try { return JSON.parse(t); } catch (e) { return null; }
    }
    return null;
  }
  if (p && typeof p.data === 'string') {
    try { return JSON.parse(p.data); } catch (e) { return null; }
  }
  return p || null;
}

const found = new Map();

function add(text, source) {
  const clean = String(text || '')
    .replace(/<\/?b>/gi, '')
    .replace(/&[a-z]+;/gi, ' ')
    .replace(/\s+/g, ' ')
    .trim();
  if (clean.length < 3 || clean.length > 120) { return; }
  // A suggestion that does not contain the brand is somebody else's problem.
  if (brandKey && clean.toLowerCase().indexOf(brandKey) < 0) { return; }
  const key = clean.toLowerCase();
  if (key === brandKey) { return; }
  if (!found.has(key)) {
    found.set(key, { suggestion: clean, suggestion_key: key, source: source });
  }
}

for (const item of $input.all()) {
  const parsed = unwrap(item.json);
  if (!parsed) { continue; }

  // Autocomplete: a two-element array whose second element is the list.
  if (Array.isArray(parsed) && Array.isArray(parsed[1])) {
    for (const row of parsed[1]) {
      add(Array.isArray(row) ? row[0] : row, 'autocomplete');
    }
    continue;
  }

  // SERP: People Also Ask and the related searches under the results.
  for (const q of parsed.people_also_ask || []) {
    add(q && q.question, 'people also ask');
  }
  for (const r of parsed.related || parsed.related_searches || []) {
    add(r && (r.text || r.title), 'related search');
  }
}

const suggestions = [...found.values()];
if (!suggestions.length) {
  throw new Error('Neither the autocomplete endpoint nor the search returned anything for "' + brand + '". Check the Bright Data zone names in Settings.');
}

return suggestions.map(function (s) { return { json: s }; });

// What is new since the last run, and what each new one looks like before a
// model sees it.
//
// The keyword pass is deliberately first. "brand scam" and "brand lawsuit" do
// not need a language model to be recognised as a problem, and a rule that
// fires on them cannot be talked out of it by a persuasive paragraph. The model
// is there for the ones the rules cannot place.
const cfg = $('Settings').first().json;
const brand = String(cfg.brand || '');

const DAMAGING = [
  'scam', 'fraud', 'lawsuit', 'sue', 'suing', 'complaint', 'refund', 'shut down',
  'shutting down', 'data breach', 'hacked', 'layoff', 'layoffs', 'bankrupt',
  'down detector', 'not working', 'cancel', 'cancellation', 'unsubscribe',
  'rip off', 'ripoff', 'fake', 'legit', 'safe', 'reddit complaints', 'class action',
];
const COMPETITIVE = [
  ' vs ', ' vs.', 'alternative', 'alternatives', 'competitor', 'competitors',
  'instead of', 'compared to', 'better than', 'or ',
];

const seen = new Map();
for (const i of $('Read What You Saw Last Time').all()) {
  const r = i.json || {};
  if (r.suggestion_key) { seen.set(String(r.suggestion_key).toLowerCase(), r); }
}

const today = new Date().toISOString().slice(0, 10);
const all = $('Read The Suggestions').all().map(function (i) { return i.json; });

function classify(text) {
  const t = ' ' + text.toLowerCase() + ' ';
  if (DAMAGING.some(function (w) { return t.indexOf(w) >= 0; })) { return 'damaging'; }
  if (COMPETITIVE.some(function (w) { return t.indexOf(w) >= 0; })) { return 'competitive'; }
  return 'unclear';
}

const rows = all.map(function (s) {
  const prior = seen.get(s.suggestion_key);
  return Object.assign({}, s, {
    rule_verdict: classify(s.suggestion),
    is_new: !prior,
    first_seen: prior ? prior.first_seen : today,
    last_seen: today,
  });
});

const fresh = rows.filter(function (r) { return r.is_new; });

// Only the new ones the rules could not place are worth a model call. On a
// quiet day that is zero, and the run costs nothing beyond the two searches.
const toJudge = fresh.filter(function (r) { return r.rule_verdict === 'unclear'; }).slice(0, 40);

// A step that can return nothing ends the branch, and the quiet path below it
// would never fire. One marker item always comes back.
return [{ json: {
  has_new: fresh.length > 0,
  brand: brand,
  total: rows.length,
  new_count: fresh.length,
  rows: rows,
  fresh: fresh,
  to_judge: toJudge.map(function (r) { return r.suggestion; }).join('\n'),
  judge_count: toJudge.length,
}}];

parameters.text:
=You are watching what Google suggests when someone types a brand name.

BRAND: {{ $json.brand }}
WHAT THE COMPANY DOES: {{ $('Settings').first().json.brand_context }}

NEW SUGGESTIONS, one per line:
{{ $json.to_judge }}

For each line, decide whether it is bad for the brand, a comparison against someone else, or neither.

Answer with JSON and nothing else:
{"verdicts": [{"suggestion": "", "verdict": "damaging", "note": ""}]}

verdict must be exactly one of: damaging, competitive, neutral.
damaging: a buyer typing this is unhappy, suspicious, or leaving.
competitive: they are weighing you against somebody else.
neutral: ordinary product or support interest.
note: at most eight words on why. No advice, no recommendations - just what the person typing it probably wants.

