// Merge the model's opinion back over the rule verdicts.
//
// The rules win where they fired. A model that decides "brand lawsuit" is
// neutral is wrong, and the cheapest way to never have that argument is to not
// ask the question.
//
// single-item input: one judging call covers the whole batch.
const found = $('Find What Is New').first().json;
const raw = String(($input.first().json || {}).text || '');

const VERDICTS = ['damaging', 'competitive', 'neutral'];

function objectsIn(text) {
  const out = [];
  // Every open brace is remembered and every matching close is parsed, at any
  // depth. Collecting only top-level objects looks equivalent and is not: when
  // the answer is cut off, the outer wrapper never closes, so a top-level-only
  // scan returns nothing at all while the individual records inside it are
  // sitting there complete.
  const stack = [];
  let inString = false;
  let escaped = false;
  for (let i = 0; i < text.length; i += 1) {
    const c = text[i];
    if (inString) {
      if (escaped) { escaped = false; }
      else if (c === '\\') { escaped = true; }
      else if (c === '"') { inString = false; }
      continue;
    }
    if (c === '"') { inString = true; continue; }
    if (c === '{') { stack.push(i); continue; }
    if (c === '}' && stack.length) {
      const s = stack.pop();
      try { out.push(JSON.parse(text.slice(s, i + 1))); } catch (e) { /* skip */ }
    }
  }
  return out;
}

const judged = {};
const objects = objectsIn(raw);
let list = [];
for (const o of objects) {
  if (Array.isArray(o.verdicts)) { list = o.verdicts; break; }
}
if (!list.length) {
  list = objects.filter(function (o) { return o && o.suggestion && o.verdict; });
}

for (const row of list) {
  const key = String((row && row.suggestion) || '').toLowerCase().trim();
  // The model ignores an enum often enough to plan for: "Damaging", "negative"
  // and "harmful" have all come back where three lowercase words were asked
  // for. Anything off the list becomes unclear rather than becoming a new
  // category nobody defined.
  let v = String((row && row.verdict) || '').toLowerCase().trim();
  if (VERDICTS.indexOf(v) < 0) { v = 'unclear'; }
  if (key) { judged[key] = { verdict: v, note: String((row && row.note) || '').slice(0, 200) }; }
}

const rows = (found.rows || []).map(function (r) {
  const j = judged[r.suggestion.toLowerCase()];
  const verdict = r.rule_verdict !== 'unclear' ? r.rule_verdict : (j ? j.verdict : 'unclear');
  return Object.assign({}, r, {
    verdict: verdict,
    note: r.rule_verdict !== 'unclear' ? 'matched a keyword rule' : (j ? j.note : ''),
  });
});

const fresh = rows.filter(function (r) { return r.is_new; });
const damaging = fresh.filter(function (r) { return r.verdict === 'damaging'; });
const competitive = fresh.filter(function (r) { return r.verdict === 'competitive'; });
const other = fresh.filter(function (r) { return r.verdict !== 'damaging' && r.verdict !== 'competitive'; });

function line(r) {
  return '- `' + r.suggestion + '`  _(' + r.source + ')_' + (r.note ? ' - ' + r.note : '');
}

const parts = ['*What Google now suggests about ' + found.brand + '*'];
if (damaging.length) {
  parts.push('\n*' + damaging.length + ' worth acting on*\n' + damaging.map(line).join('\n'));
}
if (competitive.length) {
  parts.push('\n*' + competitive.length + ' comparison or alternative*\n' + competitive.map(line).join('\n'));
}
if (other.length) {
  parts.push('\n*' + other.length + ' other new suggestion' + (other.length === 1 ? '' : 's') + '*\n' + other.slice(0, 10).map(line).join('\n'));
}
parts.push('\n' + found.total + ' suggestions tracked in total.');

return [{ json: {
  message: parts.join('\n'),
  rows: rows,
  damaging: damaging.length,
  competitive: competitive.length,
  new_count: fresh.length,
}}];

// The upsert emits one item per suggestion. Without executeOnce the digest
// would be assembled once per row and Slack would receive it forty times.
//
// single-item input: the message was built upstream and is read back rather
// than rebuilt from the rows now in flight.
const found = $('Read The Verdicts').first().json;

return [{ json: {
  message: found.message,
  damaging: found.damaging,
  new_count: found.new_count,
}}];
